233	impl Timers {
234	    pub fn new<T: Tun, B: UDP>(
235	        wg: WireGuard<T, B>, // WireGuard device
236	        pk: PublicKey,       // public key of peer
237	        running: bool,       // timers started
238	    ) -> Timers {
239	        macro_rules! fetch_peer {
240	            ( $wg:expr, $pk:expr, $peer:ident) => {
241	                let peers = $wg.peers.read();
242	                let $peer = match peers.get(&$pk) {
243	                    None => {
244	                        return;
245	                    }
246	                    Some(peer) => peer,
247	                };
248	            };
249	        }
250	
251	        macro_rules! fetch_timers {
252	            ( $peer:ident, $timers:ident) => {
253	                let $timers = $peer.timers();
254	                if !$timers.enabled {
255	                    return;
256	                }
257	            };
258	        }
259	
260	        let runner = wg.runner.lock();
261	
262	        // create a timer instance for the provided peer
263	        Timers {
264	            enabled: running,
265	            keepalive_interval: 0, // disabled
266	            need_another_keepalive: AtomicBool::new(false),
267	            sent_lastminute_handshake: AtomicBool::new(false),
268	            handshake_attempts: AtomicUsize::new(0),
269	            retransmit_handshake: {
270	                let wg = wg.clone();
271	                runner.timer(move || {
272	                    // fetch peer by public key
273	                    fetch_peer!(wg, pk, peer);
274	                    fetch_timers!(peer, timers);
275	
276	                    // check if handshake attempts remaining
277	                    let attempts = timers.handshake_attempts.fetch_add(1, Ordering::SeqCst);
278	                    if attempts > MAX_TIMER_HANDSHAKES {
279	                        debug!(
280	                            "Handshake for peer {} did not complete after {} attempts, giving up",
281	                            peer,
282	                            attempts + 1
283	                        );
284	                        timers.send_keepalive.stop();
285	                        timers.zero_key_material.start(REJECT_AFTER_TIME * 3);
286	                        peer.purge_staged_packets();
287	                    } else {
288	                        debug!(
289	                            "Handshake for {} did not complete after {} seconds, retrying (try {})",
290	                            peer,
291	                            REKEY_TIMEOUT.as_secs(),
292	                            attempts
293	                        );
294	                        timers.retransmit_handshake.reset(REKEY_TIMEOUT);
295	                        peer.clear_src();
296	                        peer.packet_send_queued_handshake_initiation(true);
297	                    }
298	                })
299	            },
300	            send_keepalive: {
301	                let wg = wg.clone();
302	                runner.timer(move || {
303	                    // fetch peer by public key
304	                    fetch_peer!(wg, pk, peer);
305	                    fetch_timers!(peer, timers);
306	
307	                    // send keepalive and schedule next keepalive
308	                    peer.send_keepalive();
309	                    if timers.need_another_keepalive() {
310	                        timers.send_keepalive.start(KEEPALIVE_TIMEOUT);
311	                    }
312	                })
313	            },
314	            new_handshake: {
315	                let wg = wg.clone();
316	                runner.timer(move || {
317	                    // fetch peer by public key
318	                    fetch_peer!(wg, pk, peer);
319	                    fetch_timers!(peer, timers);
320	
321	                    // clear source and retry
322	                    log::debug!(
323	                        "Retrying handshake with {} because we stopped hearing back after {} seconds",
324	                        peer,
325	                        (KEEPALIVE_TIMEOUT + REKEY_TIMEOUT).as_secs()
326	                    );
327	                    peer.clear_src();
328	                    peer.packet_send_queued_handshake_initiation(false);
329	                })
330	            },
331	            zero_key_material: {
332	                let wg = wg.clone();
333	                runner.timer(move || {
334	                    // fetch peer by public key
335	                    fetch_peer!(wg, pk, peer);
336	                    log::trace!("{} : timer fired (zero_key_material)", peer);
337	
338	                    // null all key-material
339	                    peer.zero_keys();
340	                })
341	            },
342	            send_persistent_keepalive: {
343	                let wg = wg.clone();
344	                runner.timer(move || {
345	                    // fetch peer by public key
346	                    fetch_peer!(wg, pk, peer);
347	                    fetch_timers!(peer, timers);
348	                    log::trace!("{} : timer fired (send_persistent_keepalive)", peer);
349	
350	                    // send and schedule persistent keepalive
351	                    if timers.keepalive_interval > 0 {
352	                        timers.send_keepalive.stop();
353	                        peer.send_keepalive();
354	                        log::trace!("{} : keepalive queued", peer);
355	                        timers
356	                            .send_persistent_keepalive
357	                            .start(Duration::from_secs(timers.keepalive_interval));
358	                    }
359	                })
360	            },
361	        }
362	    }
363	}
