365	impl<T: Tun, B: UDP> Callbacks for PeerInner<T, B> {
366	    type Opaque = Self;
367	
368	    /* Called after the router encrypts a transport message destined for the peer.
369	     * This method is called, even if the encrypted payload is empty (keepalive)
370	     */
371	    #[inline(always)]
372	    fn send(peer: &Self::Opaque, size: usize, sent: bool, keypair: &Arc<KeyPair>, counter: u64) {
373	        log::trace!("{} : EVENT(send)", peer);
374	
375	        // update timers and stats
376	
377	        peer.timers_any_authenticated_packet_traversal();
378	        peer.timers_any_authenticated_packet_sent();
379	        peer.tx_bytes.fetch_add(size as u64, Ordering::Relaxed);
380	        if size > message_data_len(0) && sent {
381	            peer.timers_data_sent();
382	        }
383	
384	        // keep_key_fresh
385	
386	        fn keep_key_fresh(keypair: &Arc<KeyPair>, counter: u64) -> bool {
387	            counter > REKEY_AFTER_MESSAGES
388	                || (keypair.initiator && Instant::now() - keypair.birth > REKEY_AFTER_TIME)
389	        }
390	
391	        if keep_key_fresh(keypair, counter) {
392	            peer.packet_send_queued_handshake_initiation(false);
393	        }
394	    }
395	
396	    /* Called after the router successfully decrypts a transport message from a peer.
397	     * This method is called, even if the decrypted packet is:
398	     *
399	     * - A keepalive
400	     * - A malformed IP packet
401	     * - Fails to cryptkey route
402	     */
403	    #[inline(always)]
404	    fn recv(peer: &Self::Opaque, size: usize, sent: bool, keypair: &Arc<KeyPair>) {
405	        log::trace!("{} : EVENT(recv)", peer);
406	
407	        // update timers and stats
408	
409	        peer.timers_any_authenticated_packet_traversal();
410	        peer.timers_any_authenticated_packet_received();
411	        peer.rx_bytes.fetch_add(size as u64, Ordering::Relaxed);
412	        if size > 0 && sent {
413	            peer.timers_data_received();
414	        }
415	
416	        // keep_key_fresh
417	
418	        #[inline(always)]
419	        fn keep_key_fresh(keypair: &Arc<KeyPair>) -> bool {
420	            Instant::now() - keypair.birth > REJECT_AFTER_TIME - KEEPALIVE_TIMEOUT - REKEY_TIMEOUT
421	        }
422	
423	        if keep_key_fresh(keypair)
424	            && !peer
425	                .timers()
426	                .sent_lastminute_handshake
427	                .swap(true, Ordering::Acquire)
428	        {
429	            peer.packet_send_queued_handshake_initiation(false);
430	        }
431	    }
432	
433	    /* Called every time the router detects that a key is required,
434	     * but no valid key-material is available for the particular peer.
435	     *
436	     * The message is called continuously
437	     * (e.g. for every packet that must be encrypted, until a key becomes available)
438	     */
439	    #[inline(always)]
440	    fn need_key(peer: &Self::Opaque) {
441	        log::trace!("{} : EVENT(need_key)", peer);
442	        peer.packet_send_queued_handshake_initiation(false);
443	    }
444	
445	    #[inline(always)]
446	    fn key_confirmed(peer: &Self::Opaque) {
447	        log::trace!("{} : EVENT(key_confirmed)", peer);
448	        peer.timers_handshake_complete();
449	    }
450	}
